const B2 = `linear-gradient(180deg, color-mix(in srgb, var(--acc2) 85%, #000), color-mix(in srgb, var(--acc2) 65%, #000))`;

root.innerHTML = `
  <div id="c0" style="${STY(B1)}top:80px;">
    <div style="font-size:46px;margin-bottom:20px;opacity:0.8">OCTOBER REVENUE</div>
    <div style="font-size:110px;letter-spacing:-2px">$81 BILLION</div>
    <div style="font-size:46px;margin-top:20px;opacity:0.8">RUN-RATE</div>
  </div>
  <div id="c1" style="${STY(B2)}top:560px;">
    <div style="font-size:46px;margin-bottom:20px;opacity:0.8">FOUNDER CONTROL</div>
    <div style="font-size:110px;letter-spacing:-2px">>50%</div>
    <div style="font-size:46px;margin-top:20px;opacity:0.8">VOTING POWER</div>
  </div>
  <svg style="position:absolute;width:940px;height:1060px;fill:none;stroke:#ffffff;stroke-width:8;stroke-linecap:round;opacity:0.3">
    <path id="l0" d="M470 460 L470 560" />
  </svg>
`;

const items = [root.querySelector('#c0'), root.querySelector('#c1')];
const line = root.querySelector('#l0');
const len = line.getTotalLength();
line.style.strokeDasharray = len;
line.style.strokeDashoffset = len;

function frame(t, p, d) {
  const s1 = spr(t, 0.4, 0.85, 7);
  const s2 = spr(t, 1.4, 0.85, 7);
  const sL = spr(t, 2.2, 0.9, 6);

  // First Card Entrance
  items[0].style.opacity = clamp(s1 * 1.5);
  items[0].style.transform = `translateY(${lerp(60, 0, E_OUT(s1))}px) scale(${lerp(0.92, 1, s1)})`;

  // Second Card Entrance
  items[1].style.opacity = clamp(s2 * 1.5);
  items[1].style.transform = `translateY(${lerp(60, 0, E_OUT(s2))}px) scale(${lerp(0.92, 1, s2)})`;

  // Connector Line
  line.style.strokeDashoffset = lerp(len, 0, E_OUT(sL));
  line.style.opacity = lerp(0, 0.3, clamp(sL * 2));

  // Settle everything early for the loop hold
  if (p > 0.55) {
    items[0].style.opacity = 1;
    items[0].style.transform = 'none';
    items[1].style.opacity = 1;
    items[1].style.transform = 'none';
    line.style.strokeDashoffset = 0;
    line.style.opacity = 0.3;
  }
}
